struct Job {
    input: String,
    artifact: Option<ExportArtifact>,
    reply: Value,
    born: Instant,
    confirmed: bool,
}
struct GenerationGuard {
    state: Arc<Mutex<ExportStore>>,
    id: String,
}
impl Drop for GenerationGuard {
    fn drop(&mut self) {
        if let Ok(mut store) = self.state.lock()
            && let Some(job) = store.jobs.get_mut(&self.id)
            && job.reply["status"] == "pending"
        {
            let external = serde_json::from_str::<Value>(&job.input)
                .is_ok_and(|input| matches!(input["format"].as_str(), Some("doc" | "wps")));
            job.reply = if external {
                failed_reply(
                    &self.id,
                    "resultUnknown",
                    UiMessage::error_api_export_interrupted_external_conversion(),
                )
            } else {
                failed_reply(
                    &self.id,
                    "generationInterrupted",
                    UiMessage::error_api_export_interrupted_generation(),
                )
            };
            job.born = Instant::now();
        }
    }
}
#[derive(Default)]
pub(crate) struct ExportStore {
    pub(crate) recognition: crate::recognition_api::Store,
    queries: HashMap<String, FrozenQueryOutput>,
    jobs: HashMap<String, Job>,
    expired: std::collections::BTreeSet<String>,
    legacy_root: Option<PathBuf>,
    legacy_active: HashMap<String, Arc<AtomicBool>>,
    legacy_queued_cancels: std::collections::BTreeSet<String>,
    closing: bool,
}
impl ExportStore {
    pub(crate) fn close(&mut self) {
        self.closing = true;
        self.recognition.close();
        for cancel in self.legacy_active.values() {
            cancel.store(true, Ordering::Release);
        }
    }
    pub(crate) fn with_legacy_root(root: PathBuf) -> Self {
        Self {
            recognition: crate::recognition_api::Store::new(root.with_file_name("recognition")),
            legacy_root: Some(root),
            ..Self::default()
        }
    }
    fn prune(&mut self) {
        self.queries.retain(|_, q| q.born.elapsed() < TTL);
        self.jobs.retain(|id, j| {
            if j.born.elapsed() < TTL || j.reply["status"] == "pending" {
                return true;
            }
            self.expired.insert(id.clone());
            false
        });
    }
    fn size(&self) -> usize {
        self.jobs
            .values()
            .map(|j| {
                j.artifact.as_ref().map_or(0, |a| a.bytes.len())
                    + j.input.len()
                    + j.reply.to_string().len()
            })
            .sum::<usize>()
            + self
                .queries
                .values()
                .map(|q| q.value.to_string().len() + q.schema.to_string().len())
                .sum::<usize>()
    }
}
fn store(state: &AppState) -> Result<std::sync::MutexGuard<'_, ExportStore>, ApiError> {
    state
        .exports
        .lock()
        .map_err(|_| ApiError::internal(UiMessage::error_api_export_session_unavailable()))
}

